'use strict';
const $=q=>document.querySelector(q);
const $$=q=>[...document.querySelectorAll(q)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>'Rs '+Number(v||0).toLocaleString('en-PK',{minimumFractionDigits:0,maximumFractionDigits:2});
const num=v=>Number(v||0).toLocaleString('en-PK');
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Karachi',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const clockToday=()=>{const p=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Karachi',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const g=k=>p.find(x=>x.type===k).value;return `${g('year')}-${g('month')}-${g('day')}`;};
const state={token:localStorage.getItem('aqua_token'),me:null,plant:null,view:'dashboard',customers:[],staff:[],routes:[],orders:[],search:''};
const pageMeta={products:['Bottle catalog','PRODUCTS & PRICING','Manage bottle capacities, default prices and stock alerts.'],dashboard:['Dashboard','OPERATIONS OVERVIEW','Monitor daily sales, bottle stock and outstanding balances.'],customers:['Customers','CUSTOMER DIRECTORY','Manage customer records and bottle receivables.'],orders:['Delivery orders','ORDER WORKSPACE','Plan and fulfill daily water delivery requests.'],deliveries:['Deliveries','DELIVERY HISTORY','Every bottle delivered and every empty collected.'],invoices:['Invoice center','BILLING & WHATSAPP','Download branded PDF invoices and open customer WhatsApp chats.'],collections:['Collections desk','RECEIVABLES FOLLOW-UP','Track unpaid customer balances and prepare personalized reminders.'],subscriptions:['Recurring plans','AUTOMATED SCHEDULING','Generate delivery orders for repeat customers.'],payments:['Payments','COLLECTIONS','Track customer collections and payment methods.'],stock:['Bottle inventory','ASSET CONTROL','Keep full, empty and circulating bottles accounted for.'],production:['Production','PLANT OPERATIONS','Record the filling of sanitized empty bottles.'],routes:['Delivery routes','FIELD OPERATIONS','Organize geographic delivery rounds.'],quality:['Quality log','WATER QUALITY','Keep records of point-in-time measurements.'],maintenance:['Maintenance','EQUIPMENT CARE','Schedule and close planned maintenance tasks.'],expenses:['Operating expenses','COSTS & OUTGOINGS','Record plant running costs and other payments.'],reports:['Reports & analytics','MANAGEMENT REPORTS','Compare sales, collections and cash movements.'],staff:['Team accounts','ACCESS CONTROL','Create manager and driver accounts.'],settings:['Settings & backup','ADMINISTRATION','Manage business details and export records.']};
let toastTimer;
function toast(s,error=false){const el=$('#toast');el.textContent=s;el.hidden=false;el.classList.toggle('error',error);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4400);}
async function api(path,options={}){const headers={'Content-Type':'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{})};let r;try{r=await fetch('/api'+path,{headers,...options});}catch(e){throw Error('Cannot connect to server. Check that AquaLedger is running.');}if(r.status===401&&state.me){logout();throw Error('Session expired, please sign in again.');}if(!r.ok){const d=await r.json().catch(()=>({}));throw Error(typeof d.detail==='string'?d.detail:Array.isArray(d.detail)?d.detail.map(x=>`${(x.loc||[]).slice(-1)}: ${x.msg}`).join('; '):r.status===401?'Login was rejected without an AquaLedger error. If using a protected tunnel, refresh its email authentication and check server logs.':`Request failed (${r.status})`);}return r.json();}
const post=(url,body)=>api(url,{method:'POST',body:JSON.stringify(body)});
async function download(path,filename){const r=await fetch('/api'+path,{headers:{Authorization:'Bearer '+state.token}});if(!r.ok)throw Error('Download failed');const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function logout(){localStorage.removeItem('aqua_token');state.token=null;state.me=null;$('#app').hidden=true;$('#auth-screen').hidden=false;}
$('#auth-form').onsubmit=async e=>{e.preventDefault();const b=$('#auth-submit');b.disabled=true;const f=Object.fromEntries(new FormData(e.target));try{const a=await post('/auth/login',f);state.token=a.token;localStorage.setItem('aqua_token',a.token);e.target.reset();await enter();}catch(x){toast(x.message,true);}finally{b.disabled=false;}};
async function enter(){try{state.me=await api('/me');state.plant=await api('/settings');$('#auth-screen').hidden=true;$('#app').hidden=false;$('#profile-name').textContent=state.me.name;$('#profile-role').textContent=state.me.role;$('#avatar').textContent=state.me.name[0]?.toUpperCase();$('#plant-label').textContent=state.plant.name;$('#today-chip').textContent=new Date().toLocaleDateString('en-PK',{timeZone:'Asia/Karachi',day:'numeric',month:'short',year:'numeric'});$('#nav [data-view="staff"]').hidden=state.me.role==='driver';const isDriver=state.me.role==='driver';for(const v of ['dashboard','invoices','collections','subscriptions','production','quality','maintenance','expenses','reports','settings','stock','products']){$(`#nav [data-view="${v}"]`).hidden=isDriver;}await caches();await show(isDriver?'orders':'dashboard');}catch(x){logout();toast(x.message,true);}}
async function caches(){const [c,r,p,s]=await Promise.all([api('/customers'),api('/routes'),api('/products'),state.me.role!=='driver'?api('/staff'):Promise.resolve([])]);state.customers=c;state.routes=r;state.products=p;state.staff=s;}
$('#logout').onclick=logout;$('#password-change').onclick=()=>form('Change your password',[{key:'current_password',label:'Current password',type:'password',required:true},{key:'new_password',label:'New password (8+ characters)',type:'password',required:true,minlength:8}],async r=>{await post('/auth/change-password',r);logout();toast('Password updated. Please sign in again.');});
$('#menu-toggle').onclick=()=>{$('#sidebar').classList.add('open');$('#shade').hidden=false;};$('#shade').onclick=()=>{$('#sidebar').classList.remove('open');$('#shade').hidden=true;};
$$('[data-view]').forEach(x=>x.onclick=()=>show(x.dataset.view));
function action(label,onClick,secondary=false){const b=document.createElement('button');b.type='button';b.className=secondary?'btn btn-secondary':'btn btn-primary';b.textContent=label;b.onclick=onClick;$('#page-actions').appendChild(b);}
function setActions(...specs){$('#page-actions').replaceChildren();specs.forEach(s=>action(s[0],s[1],s[2]));}
async function show(view){if(view==='invoices'&&state.view!=='invoices')state.invoicePage=0;state.view=view;state.search='';$('#sidebar').classList.remove('open');$('#shade').hidden=true;$$('[data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===view));const [title,overline,desc]=pageMeta[view];$('#page-title').textContent=title;$('#page-overline').textContent=overline;$('#page-desc').textContent=desc;$('#crumb').textContent=title;$('#page-actions').replaceChildren();$('#page-body').innerHTML='<div class="empty-state">Loading workspace…</div>';
try{const renderer=views[view];if(!renderer)throw Error('Unknown page');await renderer();}catch(e){$('#page-body').innerHTML=`<div class="empty-state"><strong>Could not load page</strong>${esc(e.message)}</div>`;toast(e.message,true);}}
function metric(label,value,icon,foot=''){return `<div class="kpi"><div class="kpi-icon">${icon}</div><div class="label">${esc(label)}</div><div class="metric">${esc(value)}</div><small>${esc(foot)}</small></div>`;}
function panel(title,html,right=''){return `<section class="panel"><div class="panel-head"><h3>${esc(title)}</h3><span>${esc(right)}</span></div>${html}</section>`;}
function line(label,meta,val){return `<div class="list-line"><div><strong>${esc(label)}</strong><small>${esc(meta)}</small></div><span class="amount">${esc(val)}</span></div>`;}
function empty(heading='Nothing here yet',desc='Add your first record to get started.'){return `<div class="empty-state"><div class="empty-icon">◈</div><strong>${esc(heading)}</strong>${esc(desc)}</div>`;}
function pill(s){const cl=String(s).toLowerCase();const color=cl==='delivered'||cl==='completed'||cl==='active'?'green':cl==='cancelled'||cl==='overdue'?'red':'orange';return `<span class="pill pill-${color}">${esc(s)}</span>`;}
function table(headers,rows){if(!rows.length)return empty();return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(s=>`<th>${esc(s)}</th>`).join('')}</tr></thead><tbody>${rows.map(cols=>`<tr>${cols.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
const btn=(act,id,label)=>`<button class="mini-button" data-act="${esc(act)}" data-id="${Number(id)}">${esc(label)}</button>`;
async function refresh(){await caches();await show(state.view);}
const buttons={};$('#page-body').addEventListener('click',async e=>{const target=e.target.closest('button[data-act]');if(!target)return;const fn=buttons[target.dataset.act];if(fn)try{await fn(Number(target.dataset.id));}catch(ex){toast(ex.message,true);}});
function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();}$('#close-modal').onclick=()=>$('#modal').close();
function form(title,fields,submit,info=''){const markup=fields.map(f=>{const attrs=`name="${esc(f.key)}" ${f.required?'required':''} ${f.min!==undefined?`min="${f.min}"`:''} ${f.max!==undefined?`max="${f.max}"`:''} ${f.step?`step="${f.step}"`:''} ${f.minlength?`minlength="${f.minlength}"`:''} ${f.maxlength?`maxlength="${f.maxlength}"`:''} `;
const def=f.value??(f.type==='date'?clockToday():'');let content='';
if(f.type==='select'){content=`<select ${attrs}>${(f.options||[]).map(o=>`<option value="${esc(o[0])}" ${String(o[0])===String(def)?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`;}
else if(f.type==='textarea'){content=`<textarea ${attrs} placeholder="${esc(f.placeholder||'')}">${esc(def)}</textarea>`;}
else content=`<input type="${esc(f.type||'text')}" ${attrs} value="${esc(def)}" placeholder="${esc(f.placeholder||'')}" ${f.type==='number'?`step="${f.step||1}"`:''}>`;
return `<label class="${f.wide?'wide':''}"><span class="field-caption">${esc(f.label)}${f.required?'<span class="req" aria-label="required">*</span>':''}</span>${content}</label>`;}).join('');
modal(title,`<form id="entry-form" class="dialog-form"><div class="dialog-fields">${markup}</div>${info?`<div class="notice">${esc(info)}</div>`:''}<div class="dialog-actions"><button type="button" class="btn" id="cancel-form">Cancel</button><button class="btn btn-primary" type="submit">Save record</button></div></form>`);
$('#cancel-form').onclick=()=>$('#modal').close();$('#entry-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter||$('#entry-form button[type=submit]');b.disabled=true;const fd=new FormData(e.target);const record={};for(const f of fields){let val=fd.get(f.key);if(f.type==='number')val=Number(val||0);if(f.type==='select'&&f.integer)val=val===''?null:Number(val);if(f.type==='text'&&f.integer)val=Number(val);record[f.key]=val;}try{await submit(record);$('#modal').close();if(!state.token)return;toast('Saved successfully');await refresh();}catch(ex){toast(ex.message,true);}finally{b.disabled=false;}};
}
