const updatePrice=async()=>{const request=++priceRequest;manualPrice=false;saveButton.disabled=true;try{const rows=await api('/customers/'+customerSelect.value+'/bottle-sizes');if(request!==priceRequest||$('#entry-form')!==deliveryForm||manualPrice)return;priceInput.value=rows.find(p=>p.id==sizeSelect.value)?.price??0;updateSummary();}catch(e){if($('#entry-form')===deliveryForm)toast(e.message,true);}finally{if(request===priceRequest)saveButton.disabled=false;}};
