// Customer communications are user initiated; wa.me never sends messages automatically.
function normalizeWhatsApp(raw){
  const digits=String(raw||'').replace(/\D/g,'');
  if(/^03\d{9}$/.test(digits))return '92'+digits.slice(1);
  if(/^923\d{9}$/.test(digits))return digits;
  if(/^0092\d{10}$/.test(digits))return digits.slice(2);
  if(/^\d{10,15}$/.test(digits)&&!digits.startsWith('0'))return digits;
  return '';
}
function whatsappUrl(phone,text){const number=normalizeWhatsApp(phone);if(!number)throw Error('Invalid WhatsApp number. Enter a Pakistani mobile such as 03001234567 or +923001234567.');return `https://wa.me/${number}?text=${encodeURIComponent(text)}`;}
function payStatus(amount){return amount>0?'Payment due':amount<0?'Advance credit':'Settled';}
function invoiceMessage(x){
  const pending=Math.max(0,x.total-x.payment_on_delivery);
  return `Assalam-o-Alaikum ${x.customer.name},\n\n*${x.plant.name} — Water Delivery Invoice*\nInvoice: ${x.number}\nDate: ${x.date}\n${x.litres}L bottles delivered: ${x.qty}\nEmpty bottles collected: ${x.empties}\nPrice / bottle: ${fmt(x.unit_price)}\nDiscount: ${fmt(x.discount)}\n*Invoice total: ${fmt(x.total)}*\nCash received during delivery: ${fmt(x.cash_received_at_delivery)}\nAllocated to this invoice: ${fmt(x.payment_on_delivery)}\n*Unpaid on this invoice: ${fmt(pending)}*\n\nCurrent account balance (all transactions): ${fmt(x.current_account_balance)}\n\nFor any clarification, contact ${x.plant.phone||x.plant.name}. Thank you.`.replace(/\\n/g,'\n');
}
function customerMessage(x){
  return `Assalam-o-Alaikum ${x.name},\n\nA friendly balance reminder from *${state.plant.name}*. Our records show an outstanding account balance of *${fmt(x.balance)}*.\nPlease confirm if you have already paid so we can reconcile the ledger.\n\nThank you. ${state.plant.phone||''}`.replace(/\\n/g,'\n');
}
function shareModal({title,subtitle,phone,message,pdfId}){
  modal(title,`<div class="share-modal modal-pad"><p class="muted">${esc(subtitle)}</p><label>Customer WhatsApp number<input id="share-phone" type="tel" value="${esc(phone||'')}" placeholder="03001234567"></label><label>Message preview (editable)<textarea id="share-message" rows="11">${esc(message)}</textarea></label><div class="share-actions"><button id="open-whatsapp" class="btn whatsapp-btn" type="button">Open WhatsApp chat ↗</button><button id="copy-share" class="btn btn-secondary" type="button">Copy message</button>${pdfId?`<button id="download-invoice" class="btn" type="button">Download invoice PDF ↓</button>`:''}</div><p class="hint">WhatsApp opens with an editable draft. You must press Send yourself. To send a PDF attachment, download it first and attach it in the WhatsApp chat. Do not send payment details to an unverified number.</p></div>`);
  $('#open-whatsapp').onclick=()=>{try{window.open(whatsappUrl($('#share-phone').value,$('#share-message').value),'_blank','noopener,noreferrer');}catch(e){toast(e.message,true);}};
  $('#copy-share').onclick=async()=>{try{await navigator.clipboard.writeText($('#share-message').value);toast('Message copied');}catch(e){toast('Clipboard permission denied',true);}};
  if(pdfId)$('#download-invoice').onclick=()=>download(`/deliveries/${pdfId}/invoice.pdf`,`invoice-${pdfId}.pdf`).catch(e=>toast(e.message,true));
}
