// All forms visibly identify mandatory fields, including dynamically created settings forms.
function markRequiredLabels(){
 document.querySelectorAll('label').forEach(label=>{
   const control=label.querySelector('input,select,textarea');
   if(!control)return;
   const ownMark=label.querySelector('.req');
   if(control.required && !ownMark){
     const anchor=label.querySelector('.field-caption');
     if(anchor){anchor.insertAdjacentHTML('beforeend','<span class="req" aria-label="required">*</span>');}
     else {const caption=document.createElement('span');caption.className='field-caption';
       const node=[...label.childNodes].find(n=>n.nodeType===3 && n.textContent.trim());
       if(node){caption.textContent=node.textContent.trim();node.remove();}
       const star=document.createElement('span');star.className='req';star.textContent='*';star.setAttribute('aria-label','required');
       caption.appendChild(star);label.insertBefore(caption,control);}
   } else if(!control.required && ownMark){ownMark.remove();}
 });
}
new MutationObserver(markRequiredLabels).observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['required']});
markRequiredLabels();
